import { readdirSync, existsSync, createReadStream } from 'node:fs';
import { resolve } from 'node:path';
import { defineConfig } from 'vite';

const ROOT = __dirname;
const REPO_ROOT = resolve(ROOT, '../..');

// Every page is a real HTML file (generated by scripts/gen-pages.mjs): the catalog and one per game.
const pages = ['frontier/index.html', ...readdirSync(resolve(ROOT, 'games')).map((id) => `games/${id}/index.html`)].filter((p) => existsSync(resolve(ROOT, p)));

// GitHub Pages serves the repository root, so the build lands there: frontier/ (catalog, bundles, covers)
// and games/<id>/index.html. Nothing else in the root is touched.
export default defineConfig({
  root: ROOT,
  base: './',
  publicDir: resolve(ROOT, 'public'),
  build: {
    outDir: REPO_ROOT,
    emptyOutDir: false,
    assetsDir: 'frontier/assets',
    target: 'es2020',
    rollupOptions: { input: Object.fromEntries(pages.map((p) => [p.replace(/\/index\.html$/, '').replace(/\//g, '-'), resolve(ROOT, p)])) },
  },
  // Dev only: the catalog also shows the original ten, whose thumbnails live in the repo root (arcade/media).
  plugins: [{
    name: 'serve-hub-media',
    configureServer(server) {
      server.middlewares.use('/arcade/media', (req, res, next) => {
        const file = resolve(REPO_ROOT, 'arcade/media', decodeURIComponent((req.url ?? '').split('?')[0]).replace(/^\//, ''));
        if (!file.startsWith(resolve(REPO_ROOT, 'arcade/media')) || !existsSync(file)) return next();
        res.setHeader('Content-Type', 'image/webp');
        createReadStream(file).pipe(res);
      });
    },
  }],
  server: { fs: { allow: [REPO_ROOT] } },
});
